SELECT DISTINCT TRUNC(s.start_time) as start_time
FROM schedule s
JOIN branch_screen bs ON s.screen_code = bs.screen_code
WHERE bs.branch_code = #{branchCode}
AND s.movie_code = #{movieCode}
ORDER BY 1

SELECT screen_code, branch_code, screen_name, screen_type
FROM branch_screen
WHERE branch_code = #{branchCode}
